class Solution {
    vector<array<int, 3>> c;
    vector<int> memo;

    int dfs(int i) {
        int& res = memo[i];
        if (res != -1) return res;
        res = c[i][2];
        for (int j = i + 1; j < (int)c.size(); j++)
            if (c[j][0] <= c[i][0] && c[j][1] <= c[i][1] && c[j][2] <= c[i][2])
                res = max(res, c[i][2] + dfs(j));
        return res;
    }

public:
    int maxHeight(vector<vector<int>>& cuboids) {
        for (auto& v : cuboids) sort(v.begin(), v.end());
        sort(cuboids.rbegin(), cuboids.rend());
        c.clear();
        for (auto& v : cuboids) c.push_back({v[0], v[1], v[2]});
        memo.assign(c.size(), -1);
        int ans = 0;
        for (int i = 0; i < (int)c.size(); i++) ans = max(ans, dfs(i));
        return ans;
    }
};

