class Solution {
    private int[][] c;
    private Integer[] memo;

    public int maxHeight(int[][] cuboids) {
        for (int[] x : cuboids) Arrays.sort(x);
        Arrays.sort(cuboids, (a, b) ->
                b[0] != a[0] ? b[0] - a[0] : (b[1] != a[1] ? b[1] - a[1] : b[2] - a[2]));
        c = cuboids;
        memo = new Integer[cuboids.length];
        int ans = 0;
        for (int i = 0; i < c.length; i++) ans = Math.max(ans, dfs(i));
        return ans;
    }

    private int dfs(int i) {
        if (memo[i] != null) return memo[i];
        int res = c[i][2];
        for (int j = i + 1; j < c.length; j++)
            if (c[j][0] <= c[i][0] && c[j][1] <= c[i][1] && c[j][2] <= c[i][2])
                res = Math.max(res, c[i][2] + dfs(j));
        return memo[i] = res;
    }
};

