var maxHeight = function(cuboids) {
    for (const c of cuboids) c.sort((a, b) => a - b);
    cuboids.sort((a, b) => b[0] - a[0] || b[1] - a[1] || b[2] - a[2]);
    const n = cuboids.length;
    const memo = new Array(n).fill(-1);
    const dfs = (i) => {
        if (memo[i] !== -1) return memo[i];
        let res = cuboids[i][2];
        for (let j = i + 1; j < n; j++) {
            if (cuboids[j][0] <= cuboids[i][0] && cuboids[j][1] <= cuboids[i][1]
                    && cuboids[j][2] <= cuboids[i][2]) {
                res = Math.max(res, cuboids[i][2] + dfs(j));
            }
        }
        return (memo[i] = res);
    };
    let ans = 0;
    for (let i = 0; i < n; i++) ans = Math.max(ans, dfs(i));
    return ans;
};

